function toNumber(value: string) {
  return value === "" ? 0 : Number(value);
}

function toNullableNumber(value: string) {
  return value === "" ? null : Number(value);
}

export const prices: DailyPrice[] = rgtiAnalysisData.split("\n").map((line) => {
  const [
    date,
    open,
    high,
    low,
    close,
    changePercent,
    volume,
    volumeAverage20,
    volumeRatioValue,
    intradayRangePercent,
    rsi,
    macd,
    macdSignal,
    macdHistogram,
    macdDirection,
    rsiSignal,
    high20Breakout,
    ma5,
    ma20,
    ma50,
    closeAfter5Days,
    changeAfter5Days,
    closeAfter10Days,
    changeAfter10Days,
    score,
    pattern,
    comment,
    source
  ] = line.split("|");

  return {
    date,
    open: toNumber(open),
    high: toNumber(high),
    low: toNumber(low),
    close: toNumber(close),
    changePercent: toNumber(changePercent) * 100,
    volume: toNumber(volume),
    volumeAverage20: toNumber(volumeAverage20),
    volumeRatio: toNumber(volumeRatioValue),
    intradayRangePercent: toNumber(intradayRangePercent) * 100,
    rsi: toNumber(rsi),
    macd: toNumber(macd),
    macdSignal: toNumber(macdSignal),
    macdHistogram: toNumber(macdHistogram),
    macdDirection: macdDirection === "上昇" ? "上昇" : "低下",
    rsiSignal,
    high20Breakout,
    ma5: toNumber(ma5),
    ma20: toNumber(ma20),
    ma50: toNumber(ma50),
    volumeAverage: toNumber(volumeAverage20),
    closeAfter5Days: toNullableNumber(closeAfter5Days),
    changeAfter5Days: changeAfter5Days === "" ? null : toNumber(changeAfter5Days) * 100,
    closeAfter10Days: toNullableNumber(closeAfter10Days),
    changeAfter10Days: changeAfter10Days === "" ? null : toNumber(changeAfter10Days) * 100,
    score: toNumber(score),
    pattern,
    comment,
    source
  };
});

function average(values: number[]) {
  if (values.length === 0) return 0;
  return values.reduce((sum, value) => sum + value, 0) / values.length;
}

function calculateRsiFromCloses(closes: number[]) {
  const target = closes.slice(-15);
  if (target.length < 2) return 50;
  let gains = 0;
  let losses = 0;
  for (let index = 1; index < target.length; index += 1) {
    const diff = target[index] - target[index - 1];
    if (diff >= 0) gains += diff;
    else losses += Math.abs(diff);
  }
  if (losses === 0) return 70;
  const rs = gains / losses;
  return 100 - (100 / (1 + rs));
}

function buildSiduPrices(): DailyPrice[] {
  const baseRows = prices.slice(-220);
  const rows = baseRows.map((price, index) => {
    const wave = Math.sin(index / 7) * 0.018 + Math.cos(index / 17) * 0.012;
    const eventMove = index === 154 ? 0.34 : index === 155 ? -0.13 : index === 186 ? 0.21 : 0;
    const trend = index * 0.00035;
    const close = Math.max(0.05, 0.16 + trend + wave + eventMove);
    const open = Math.max(0.05, close * (1 - 0.018 + Math.sin(index / 5) * 0.012));
    const high = Math.max(open, close) * (1.035 + Math.abs(Math.sin(index / 9)) * 0.035);
    const low = Math.min(open, close) * (0.965 - Math.abs(Math.cos(index / 11)) * 0.018);
    const volume = Math.round(3800000 + Math.abs(Math.sin(index / 6)) * 9000000 + (eventMove > 0 ? 42000000 : 0));
    return { date: price.date, open, high, low, close, volume };
  });

  return rows.map((row, index) => {
    const closes = rows.slice(0, index + 1).map((item) => item.close);
    const volumes = rows.slice(Math.max(0, index - 19), index + 1).map((item) => item.volume);
    const previousClose = rows[index - 1]?.close ?? row.close;
    const ma5 = average(closes.slice(-5));
    const ma20 = average(closes.slice(-20));
    const ma50 = average(closes.slice(-50));
    const volumeAverage20 = average(volumes);
    const macd = average(closes.slice(-12)) - average(closes.slice(-26));
    const previousCloses = rows.slice(0, index).map((item) => item.close);
    const previousMacd = index > 0 ? average(previousCloses.slice(-12)) - average(previousCloses.slice(-26)) : macd;
    const rsi = calculateRsiFromCloses(closes);
    const changePercent = previousClose > 0 ? ((row.close - previousClose) / previousClose) * 100 : 0;
    const volumeRatio = volumeAverage20 > 0 ? row.volume / volumeAverage20 : 0;
    const score = [
      row.close > ma20,
      ma20 > ma50,
      volumeRatio >= 1.2,
      rsi >= 40 && rsi <= 70,
      macd >= previousMacd
    ].filter(Boolean).length + (changePercent > 8 ? 1 : 0);

    return {
      date: row.date,
      open: row.open,
      high: row.high,
      low: row.low,
      close: row.close,
      changePercent,
      volume: row.volume,
      volumeAverage20,
      volumeRatio,
      intradayRangePercent: row.close > 0 ? ((row.high - row.low) / row.close) * 100 : 0,
      rsi,
      macd,
      macdSignal: previousMacd,
      macdHistogram: macd - previousMacd,
      macdDirection: macd >= previousMacd ? "上昇" : "低下",
      rsiSignal: rsi >= 70 ? "過熱" : rsi >= 55 ? "強気圏" : rsi <= 35 ? "弱気圏" : "中立",
      high20Breakout: row.close >= Math.max(...closes.slice(-20)) ? "20日高値更新" : "",
      ma5,
      ma20,
      ma50,
      volumeAverage: volumeAverage20,
      closeAfter5Days: null,
      changeAfter5Days: null,
      closeAfter10Days: null,
      changeAfter10Days: null,
      score,
      pattern: score >= 6 ? "短期上昇候補" : score <= 2 ? "リスク監視" : "",
      comment: "SIDU MVPダミーデータ。価格、出来高、RSI、MAを同じ形式で確認できます。",
      source: "MVP synthetic data"
    };
  });
}

export const siduPrices = buildSiduPrices();
